window.CARDS=window.CARDS||{};CARDS["people-kiriyama-ikuto"]=[{"i":"sc-kiriyama-ikuto-y1v7_5-p89-1","v":"y1v7.5","y":1,"o":9,"k":"","w":"horikita-manabu nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  named in the brief name hit in horikita manabu s student council brief  passing mention   one is vice president kiriyama  from the second year class b  passing mention only  listed among members to keep an eye on  class b  with nagumo s circle  vice president under the president ayanokoji must oppose","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v7_5-p89-1\"><h3><span class=\"ttl\">Ch.4: named in the brief<\/span><span class=\"meta\">Y1V7.5 · p.89<\/span><\/h3><p class=\"setup\">Name-hit in Horikita Manabu’s student-council brief.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “One is Vice President Kiriyama, from the second-year Class B.”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Listed among members to keep an eye on; Class B, with Nagumo’s circle.<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Vice President under the president Ayanokōji must oppose.<span class=\"pg\">p.89<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p123-1\">→ After: Ch.5: with Nagumo outside the theater<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v7_5-p123-1","v":"y1v7.5","y":1,"o":9,"k":"","w":"nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 5  with nagumo outside the theater name hit in the entourage list when nagumo interrupts the double date  passing mention  student council members present with nagumo   secretaries mizowaki and tonokawa  and vice president kiriyama  entry records this name  passing mention only  entourage for the karaoke outing after the arm grab","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v7_5-p123-1\"><h3><span class=\"ttl\">Ch.5: with Nagumo outside the theater<\/span><span class=\"meta\">Y1V7.5 · p.123<\/span><\/h3><p class=\"setup\">Name-hit in the entourage list when Nagumo interrupts the double date.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: student council members present with Nagumo — Secretaries Mizowaki and Tonokawa, and Vice President Kiriyama (entry records this name).<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Entourage for the karaoke outing after the arm-grab.<span class=\"pg\">p.123<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p89-1\">← Before: Ch.4: named in the brief<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p154-1\">→ After: Ch.6: the vice president’s secret offer<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v7_5-p154-1","v":"y1v7.5","y":1,"o":9,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi horikita-manabu karuizawa-kei kiriyama-ikuto","q":"kiriyama ikuto ch 6  the vice president s secret offer lone student at the isolated campus meet  ayanokoji names him before he speaks  offers intel on nagumo in exchange for first year help   sorry to keep you waiting   i ve never agreed with nagumo once  i joined the student council because i admired horikita senpai  he was my senpai from class a  well  he used to be  i suppose   nagumo promised reform  kiriyama told her   he said capable students would be promoted to class a  no matter where they d started  there are a lot of dissatisfied people at this school who feel they were placed in the wrong class   if i left  what then  nagumo would be even more free to wreak havoc  i thought it best to infiltrate his inner circle and collect information try to find an opening i could exploit  if i hand that information to horikita senpai  i m sure he can do something with it   but you ll be seeing a lot more of the senior students from this point on  once the third semester begins  the school holds a special exam that brings all three grade levels together  i went through the same thing last year  first  and second  and occasionally even third years battle it out   every student who got on nagumo s bad side has been expelled  across the board   i won t make direct contact with you after this  i ll create a random e mail account and get in touch through that  recruits him for anti nagumo work  notes the relay made nagumo notice him  threatens mutual destruction if blown  opposed since the election  stayed vp to feed intel  first years are nagumo s next target after third years graduate  admired senpai from class a  the intended recipient of the intel  accepted as ayanokoji s partner without hesitation  infiltrated nagumo s inner circle while vice president  will not break school rules  expulsion risk  even for horikita s endorsement","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v7_5-p154-1\"><h3><span class=\"ttl\">Ch.6: the vice president’s secret offer<\/span><span class=\"meta\">Y1V7.5 · p.154–159<\/span><\/h3><p class=\"setup\">Lone student at the isolated campus meet; Ayanokōji names him before he speaks; offers intel on Nagumo in exchange for first-year help.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Sorry to keep you waiting.”<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\">“I’ve never agreed with Nagumo once. I joined the student council because I admired Horikita-senpai. He was my senpai from Class A. Well, he used to be, I suppose.”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\">“Nagumo promised reform,” Kiriyama told her. “He said capable students would be promoted to Class A, no matter where they’d started. There are a lot of dissatisfied people at this school who feel they were placed in the wrong…”<span class=\"pg\">p.155<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Nagumo promised reform,” Kiriyama told her. “He said capable students would be promoted to Class A, no matter where they’d started. There are a lot of dissatisfied people at this school who feel they were placed in the wrong class.”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I left, what then? Nagumo would be even more free to wreak havoc. I thought it best to infiltrate his inner circle and collect information…try to find an opening I could exploit. If I hand that information to Horikita-senpai, I’m sure he can do something with it.”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But you’ll be seeing a lot more of the senior students from this point on. Once the third semester begins, the school holds a special exam that brings all three grade levels together. I went through the same thing last year. First, and second, and occasionally even third years battle it out.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Every student who got on Nagumo’s bad side has been expelled. Across the board.”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I won’t make direct contact with you after this. I’ll create a random e-mail account and get in touch through that.”<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Recruits him for anti-Nagumo work; notes the relay made Nagumo notice him; threatens mutual destruction if blown.<span class=\"pg\">p.154–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Opposed since the election; stayed VP to feed intel; first-years are Nagumo’s next target after third-years graduate.<span class=\"pg\">p.155–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Admired senpai from Class A; the intended recipient of the intel.<span class=\"pg\">p.155–156, 159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Accepted as Ayanokōji’s partner without hesitation.<span class=\"pg\">p.154–155<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Infiltrated Nagumo’s inner circle while vice president; will not break school rules (expulsion risk) even for Horikita’s endorsement.<span class=\"pg\">p.155–158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v7_5-p123-1\">← Before: Ch.5: with Nagumo outside the theater<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p96-1","v":"y1v8","y":1,"o":10,"k":"","w":"nagumo-miyabi yukimura-teruhiko kiriyama-ikuto","q":"kiriyama ikuto ch 3  vice president at the card table accompanies nagumo into group six s room with tsunoda and ishikura for the breakfast duty old maid  passing mention   vice president kiriyama and two other third year students accompanied him  passing mention only  finishes second in the early rounds  next to nagumo in the late first year showdown  defeats yukimura in the second round while yukimura holds the joker  no line of his own attributed on these pages   presence through nagumo s party and the game order","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p96-1\"><h3><span class=\"ttl\">Ch.3: vice president at the card table<\/span><span class=\"meta\">Y1V8 · p.96–103<\/span><\/h3><p class=\"setup\">Accompanies Nagumo into group six’s room with Tsunoda and Ishikura for the breakfast-duty Old Maid.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “Vice President Kiriyama and two other third-year students accompanied him.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Finishes second in the early rounds; next to Nagumo in the late first-year showdown.<span class=\"pg\">p.100–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Defeats Yukimura in the second round while Yukimura holds the joker.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> No line of his own attributed on these pages — presence through Nagumo’s party and the game order.<span class=\"pg\">p.96–103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p107-1\">→ After: Ch.3/4: passing mentions<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p107-1","v":"y1v8","y":1,"o":10,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto ch 3 4  passing mentions named as the next card player to finish after tsunoda  named as an alternative grouping option beside class d members and kei","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p107-1\"><h3><span class=\"ttl\">Ch.3/4: passing mentions<\/span><span class=\"meta\">Y1V8 · p.107, 120<\/span><\/h3><p class=\"setup\">Named as the next card-player to finish after Tsunoda.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Named as an alternative grouping option beside Class D members and Kei.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p96-1\">← Before: Ch.3: vice president at the card table<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p116-1\">→ After: Ch.4: the vice president’s coaching<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p116-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"kouenji-rokusuke ishizaki-daichi horikita-manabu nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  the vice president s coaching approaches the first year group in free time to correct attitude before lessons affect the large group s score   i think you should adjust your attitude a bit   you don t get to decide that  kouenji   you re too ignorant and infantile to even be called a high school student  lectures koenji on group unease  half the second years encircle when koenji answers back  names ishizaki first  then lumps  a number of you  as problems   koenji is the straw that breaks it  text notes he used to be class a  demoted after losing to nagumo  horikita s brother put them both in touch with ayanokoji  deep down wishes nagumo s downfall while still playing dutiful vice president for the large group s scores  frames evaluation as not only the final written test   instructors can take classroom behaviour into account  no further presence in chapter 4 after half 1","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p116-1\"><h3><span class=\"ttl\">Ch.4: the vice president’s coaching<\/span><span class=\"meta\">Y1V8 · p.116–119<\/span><\/h3><p class=\"setup\">Approaches the first-year group in free time to correct attitude before lessons affect the large group’s score.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I think you should adjust your attitude a bit,”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\">“You don’t get to decide that, Kouenji.”<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\">“You’re too ignorant and infantile to even be called a high school student,”<span class=\"pg\">p.117<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Lectures Kōenji on group unease; half the second-years encircle when Kōenji answers back.<span class=\"pg\">p.116–117<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Names Ishizaki first, then lumps “a number of you” as problems — Kōenji is the straw that breaks it.<span class=\"pg\">p.116–118<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Text notes he used to be Class A, demoted after losing to Nagumo; Horikita’s brother put them both in touch with Ayanokōji.<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Deep down wishes Nagumo’s downfall while still playing dutiful vice president for the large group’s scores.<span class=\"pg\">p.116–117<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Frames evaluation as not only the final written test — instructors can take classroom behaviour into account.<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No further presence in chapter 4 after half 1.<span class=\"pg\">p.147<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p107-1\">← Before: Ch.3/4: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p173-1\">→ After: Ch.6 half 2: the blocked contact<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v8-p173-1","v":"y1v8","y":1,"o":10,"k":"","w":"nagumo-miyabi ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto ch 6 half 2  the blocked contact named only in ayanokoji s contact plan  left a clue for him to find   kiriyama was in nagumo s group  even if he resented nagumo  he probably couldn t help me this time  in nagumo s group   the reason the contact fails  attempted second year channel before the asahina pivot  no presence beyond the plan line","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v8-p173-1\"><h3><span class=\"ttl\">Ch.6 half 2: the blocked contact<\/span><span class=\"meta\">Y1V8 · p.173<\/span><\/h3><p class=\"setup\">Named only in Ayanokōji’s contact plan.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Left a clue for him to find; “Kiriyama was in Nagumo’s group. Even if he resented Nagumo, he probably couldn’t help me this time.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> In Nagumo’s group — the reason the contact fails.<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Attempted second-year channel before the Asahina pivot.<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> No presence beyond the plan line.<span class=\"pg\">p.173<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v8-p116-1\">← Before: Ch.4: the vice president’s coaching<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v9-p100-1","v":"y1v9","y":1,"o":11,"k":"","w":"horikita-manabu kushida-kikyou kiriyama-ikuto","q":"kiriyama ikuto the source of manabu s report the vice president is who told manabu about kushida and nagumo  his information is what surfaces kushida s contact  ayanokoji flags that he cannot be completely trusted   manabu answers he does not know kiriyama as well as ayanokoji does  does not appear  named in the call only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v9-p100-1\"><h3><span class=\"ttl\">The source of Manabu’s report<\/span><span class=\"meta\">Y1V9 · p.100<\/span><\/h3><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> The vice president is who told Manabu about Kushida and Nagumo.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> His information is what surfaces Kushida’s contact.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Ayanokōji flags that he cannot be completely trusted — Manabu answers he does not know Kiriyama as well as Ayanokōji does.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Does not appear; named in the call only.<span class=\"pg\">p.100<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v9-p202-1\">→ After: The forum rumors<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v9-p202-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto the forum rumors meets ayanokoji at the school building after most students have gone home  ayanokoji reveals his plan to save ichinose  resists posting rumors on the forums  ayanokoji argues it would create a new relationship   i see  so you re telling me to post the rumors with my own phone  there d be no benefit in that for me at all  ayanokoji reveals kushida has already established contact with nagumo  kiriyama agrees to cooperate   why do you  horikita senpai s really placed a lot of trust in someone like you  hasn t he  recruits him to post the rumors on the school forums","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v9-p202-1\"><h3><span class=\"ttl\">The forum rumors<\/span><span class=\"meta\">Y1V9 · p.202–204<\/span><\/h3><p class=\"setup\">Meets Ayanokōji at the school building after most students have gone home; Ayanokōji reveals his plan to save Ichinose. Resists posting rumors on the forums; Ayanokōji argues it would create a new relationship. Ayanokōji reveals Kushida has already established contact with Nagumo; Kiriyama agrees to cooperate.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I see. So you’re telling me to post the rumors with my own phone? There’d be no benefit in that for me at all.”<span class=\"pg\">p.203<\/span><\/li><li class=\"q spoken\">“Why do you…… Horikita-senpai’s really placed a lot of trust in someone like you, hasn’t he?”<span class=\"pg\">p.204<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Recruits him to post the rumors on the school forums.<span class=\"pg\">p.202–204<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y1v9-p100-1\">← Before: The source of Manabu’s report<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y1v11_5-p94-1","v":"y1v11.5","y":1,"o":14,"k":"","w":"nagumo-miyabi asahina-nazuna horikita-manabu kiriyama-ikuto","q":"kiriyama ikuto ch 1  graduation farewells kiriyama appears with nagumo miyabi and other student council members during the third year farewells after the graduates  meeting  he is present in the circle around nagumo as nagumo discusses horikita manabu s graduation and the outcome of their conflict  accompanies him as a student council member during the farewells  present alongside her in the student council group  present during the farewell exchanges with the former president","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y1v11_5-p94-1\"><h3><span class=\"ttl\">Ch.1: Graduation farewells<\/span><span class=\"meta\">Y1V11.5 · p.94–104<\/span><\/h3><p class=\"setup\">Kiriyama appears with Nagumo Miyabi and other student council members during the third-year farewells after the graduates’ meeting. He is present in the circle around Nagumo as Nagumo discusses Horikita Manabu’s graduation and the outcome of their conflict.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"asahina-nazuna.html\">Asahina Nazuna<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Accompanies him as a student council member during the farewells.<span class=\"pg\">p.94–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asahina Nazuna<\/b> Present alongside her in the student council group.<span class=\"pg\">p.94–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Present during the farewell exchanges with the former president.<span class=\"pg\">p.94–98<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v2-p78-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"nagumo-miyabi horikita-suzune ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto kiriyama attends he has remained silent through the whole interview  then he speaks to nagumo for the first time   she doesn t look that similar to him  but she really is horikita senpai s little sister   i m kind of comfortable calling you horikita  i may have referred to you with that already but i ll call you suzune from now on  okay   i was troubled since the only member in the student council from the 2nd year was just honami    speaker untagged by the translation  it continues his paragraph to nagumo  unassigned as printed  he attends despite having no 1st 2nd year applicants to care about  nagumo clocks it and probes   what are you thinking  nagumo  you would even invite him into the council   it s a pleasure   what do you mean   i just was interested in horikita senpai s little sister  anything wrong with that  he has given up on overthrowing nagumo but not on attaching himself to the horikita name  he is rattled when nagumo names the real reason he came  he serves him  watched  he attaches to her arrival  calls her suzune from now on  he is shaken to see ak inside","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v2-p78-1\"><h3><span class=\"ttl\">Kiriyama attends<\/span><span class=\"meta\">Y2V2 · p.78–82<\/span><\/h3><p class=\"setup\">He has remained silent through the whole interview; then he speaks to Nagumo for the first time. He attends despite having no 1st/2nd-year applicants to care about; Nagumo clocks it and probes.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“She doesn’t look that similar to him, but she really is Horikita-senpai’s little sister!”<span class=\"pg\">p.78<\/span><\/li><li class=\"q spoken\">“I’m kind of comfortable calling you Horikita. I may have referred to you with that already but I’ll call you Suzune from now on, okay?”<span class=\"pg\">p.78<\/span><\/li><li class=\"q spoken\">“What are you thinking, Nagumo? You would even invite him into the council?”<span class=\"pg\">p.80<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “I was troubled since the only member in the student council from the 2nd year was just Honami.” — speaker untagged by the translation (it continues his paragraph to Nagumo); unassigned as printed.<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s a pleasure.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…What do you mean?”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just was interested in Horikita-senpai’s little sister, anything wrong with that?”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He has given up on overthrowing Nagumo but not on attaching himself to the Horikita name; he is rattled when Nagumo names the real reason he came.<span class=\"pg\">p.78–82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> He serves him, watched.<span class=\"pg\">p.78–82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He attaches to her arrival; calls her Suzune from now on.<span class=\"pg\">p.78–82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He is shaken to see AK inside.<span class=\"pg\">p.80–82<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v2-p83-1\">→ After: Coverage note: passing mentions<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v2-p83-1","v":"y2v2","y":2,"o":17,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto coverage note  passing mentions  well  if kiriyama hasn t given up yet  eventually he might act   next to him stood kiriyama  the vice president of the student council  who had just left   because the one who left and as returned is you  kiriyama  and so that fits the image of a loyal dog   you ve got a dirty mouth  kiriyama  it doesn t suit the image of a serious vice president   nagumo tapped kiriyama on the shoulder and interrupted him  he forced kiriyama to move away a little  and stood in front of kiryuuin   i heard something from kiriyama  i would have never thought that someone who wasn t interested in both horikita senpai or i  would be interested in ayanokouji   up till now  nagumo had competed with kiriyama s class many times in the past special exams   kiriyama simply glared at kiryuuin  who was merrily talking  but didn t interfere with their conversation  after he said that  nagumo turned his attention to kiriyama  who was waiting for him   or maybe it ll be kiriyama  who s been dying to fight me   nagumo gave instructions to withdraw and headed over to kiriyama   then there were the elites of the 3rd year  nagumo  kiriyama and kiryuuin","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v2-p83-1\"><h3><span class=\"ttl\">Coverage note: passing mentions<\/span><span class=\"meta\">Y2V2 · p.83–335<\/span><\/h3><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Well… If Kiriyama hasn’t given up yet, eventually he might act.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Next to him stood Kiriyama, the vice president of the student council, who had just left.”<span class=\"pg\">p.286<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Because the one who left and as returned is you, Kiriyama, and so that fits the image of a loyal dog.”<span class=\"pg\">p.286<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “You’ve got a dirty mouth, Kiriyama, it doesn’t suit the image of a serious vice president.”<span class=\"pg\">p.286<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nagumo tapped Kiriyama on the shoulder and interrupted him. He forced Kiriyama to move away a little, and stood in front of Kiryuuin.”<span class=\"pg\">p.287<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I heard something from Kiriyama. I would have never thought that someone who wasn’t interested in both Horikita-senpai or I, would be interested in Ayanokouji.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Up till now, Nagumo had competed with Kiriyama’s class many times in the past special exams.”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Kiriyama simply glared at Kiryuuin, who was merrily talking, but didn’t interfere with their conversation.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> After he said that, Nagumo turned his attention to Kiriyama, who was waiting for him.<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Or maybe it’ll be Kiriyama, who’s been dying to fight me.”<span class=\"pg\">p.291<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nagumo gave instructions to withdraw and headed over to Kiriyama.”<span class=\"pg\">p.292<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “then there were the elites of the 3rd year- Nagumo, Kiriyama and Kiryuuin.”<span class=\"pg\">p.335<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v2-p78-1\">← Before: Kiriyama attends<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v2-p271-1\">→ After: Kiriyama&#x27;s warning (and the bench)<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v2-p271-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"nagumo-miyabi horikita-suzune kiryuin-fuuka kiriyama-ikuto","q":"kiriyama ikuto kiriyama s warning  and the bench  he stops ayanokoji near keyaki mall  the ask is loaded   you re here   don t be in such a hurry to get this done with  it s going to take some time today   the large scale uninhabited island exam is coming at the end of the month  are you prepared   i ve formed a group of 3 without anyone from class a   i know what you must be thinking  if our class 3 b wanted to reach class a  then it s a must to win first place with a team with only our class  not only that  we would have to continue to win the following special exams by a landslide  however  that s not realistic   i wanted to personally battle nagumo in this special exam   it s been a long time since we lost the battle with nagumo and fell into class b  after which  nagumo became the student council president  and took control over the entire 3rd year  and eventually the entire school  it s safe to say that the battle of the classes has already been decided   but based on my evaluation of myself  i don t think i m any weaker than nagumo   you can form a big group of up to 6 people regardless of class  in order to win  you ll have to have an eye for talent and the ability to get people to join you  in that aspect  i don t think i can lose to nagumo   i understand where you re going with this  but is it really necessary to specifically tell me this   i don t want you to get in my way   i know that  but what i m trying to say is  i don t want to be distracted by any outsiders   i m referring to horikita suzune  who just joined the student council   there s already no point to it  he s only got a few months left as student council president  if we could do something starting from now  it wouldn t be to take his presidency  but rather to settle a personal dispute with him   that won t work  forget all thoughts about dealing with nagumo  it ll only lead to unnecessary fights   to put it politely  don t do anything   then  you swear you won t do anything  can i interpret it like that   nagumo was more or less aware of what i d been doing with horikita senpai  but since i d been following his orders  he remained calm and simply observed what happened  horikita senpai s sister joining the student council was annoying enough  so if you don t stop meddling in this   yeah   nagumo s idea  the one in which anyone can graduate from class a  you want that chance   well   anyway  you should have understood what i want to say by now   say whatever you want  the conversation is interrupted by kiryuin on the bench  he glares at her and leaves with a warning  he wants to outrun him with a team  he can t  he blames her joining for everything  he cannot stand her","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v2-p271-1\"><h3><span class=\"ttl\">Kiriyama&#x27;s warning (and the bench)<\/span><span class=\"meta\">Y2V2 · p.271–285<\/span><\/h3><p class=\"setup\">He stops Ayanokōji near Keyaki mall; the ask is loaded.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kiryuin-fuuka.html\">Kiryuin Fuuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You’re here.”<span class=\"pg\">p.272<\/span><\/li><li class=\"q spoken\">“Don’t be in such a hurry to get this done with, it’s going to take some time today.”<span class=\"pg\">p.272<\/span><\/li><li class=\"q spoken\">“The large scale uninhabited island exam is coming at the end of the month, are you prepared?”<span class=\"pg\">p.272<\/span><\/li><\/ul><details class=\"more\"><summary>24 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’ve formed a group of 3 without anyone from Class A.”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know what you must be thinking, if our Class 3-B wanted to reach Class A, then it’s a must to win first place with a team with only our class. Not only that, we would have to continue to win the following special exams by a landslide. However, that’s not realistic.”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wanted to personally battle Nagumo in this special exam.”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s been a long time since we lost the battle with Nagumo and fell into Class B. After which, Nagumo became the student council president, and took control over the entire 3rd year, and eventually the entire school. It’s safe to say that the battle of the classes has already been decided.”<span class=\"pg\">p.273<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But based on my evaluation of myself, I don’t think I’m any weaker than Nagumo.”<span class=\"pg\">p.273<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can form a big group of up to 6 people regardless of class. In order to win, you’ll have to have an eye for talent and the ability to get people to join you— In that aspect, I don’t think I can lose to Nagumo.”<span class=\"pg\">p.273<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand where you’re going with this, but is it really necessary to specifically tell me this?”<span class=\"pg\">p.274<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t want you to get in my way.”<span class=\"pg\">p.274<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know that, but what I’m trying to say is, I don’t want to be distracted by any outsiders.”<span class=\"pg\">p.274<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m referring to Horikita Suzune, who just joined the student council.”<span class=\"pg\">p.274<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s already no point to it. He’s only got a few months left as Student Council president. If we could do something starting from now, it wouldn’t be to take his presidency, but rather to settle a personal dispute with him.”<span class=\"pg\">p.275<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That won’t work. Forget all thoughts about dealing with Nagumo. It’ll only lead to unnecessary fights.”<span class=\"pg\">p.275<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To put it politely, don’t do anything.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, you swear you won’t do anything. Can I interpret it like that?”<span class=\"pg\">p.276<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo was more or less aware of what I’d been doing with Horikita-senpai. But since I’d been following his orders, he remained calm and simply observed what happened. Horikita-senpai’s sister joining the student council was annoying enough, so if you don’t stop meddling in this—”<span class=\"pg\">p.276<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Yeah.”<span class=\"pg\">p.276<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo’s idea, the one in which anyone can graduate from Class A. You want that chance.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well…”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, you should have understood what I want to say by now.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Say whatever you want-“<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The conversation is interrupted by Kiryūin on the bench; he glares at her and leaves with a warning.<span class=\"pg\">p.278–285<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> He wants to outrun him with a team; he can&#x27;t.<span class=\"pg\">p.271–285<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He blames her joining for everything.<span class=\"pg\">p.274–277<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> He cannot stand her.<span class=\"pg\">p.278–285<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v2-p83-1\">← Before: Coverage note: passing mentions<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v3-p120-1","v":"y2v3","y":2,"o":18,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama at the beach flags task he is present at the beach flags task  ayanokoji notes his presence and kiriyama warns him  he warns ayanokoji not to get in his way  he is mentioned in the context of nagumo s strategy  kiriyama is present in these scenes  see the year 2  vol  2 block for his full entry","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v3-p120-1\"><h3><span class=\"ttl\">Kiriyama at the Beach Flags Task<\/span><span class=\"meta\">Y2V3 · p.120–130<\/span><\/h3><p class=\"setup\">He is present at the Beach Flags Task; Ayanokōji notes his presence and Kiriyama warns him. He warns Ayanokōji not to get in his way. He is mentioned in the context of Nagumo&#x27;s strategy.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Kiriyama is present in these scenes; see the Year 2, Vol. 2 block for his full entry.<span class=\"pg\">p.120–130<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v3-p127-1\">→ After: Kiriyama warns Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v3-p127-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama warns ayanokoji he approaches ayanokoji at the beach flags task and warns him not to get in his way   i ll say it again just to be sure  don t get in my way  got it  hostile and on guard","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v3-p127-1\"><h3><span class=\"ttl\">Kiriyama warns Ayanokōji<\/span><span class=\"meta\">Y2V3 · p.127<\/span><\/h3><p class=\"setup\">He approaches Ayanokōji at the Beach Flags Task and warns him not to get in his way.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I&#x27;ll say it again just to be sure: Don&#x27;t get in my way, got it?&quot;<span class=\"pg\">p.127<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Hostile and on guard.<span class=\"pg\">p.127<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v3-p120-1\">← Before: Kiriyama at the Beach Flags Task<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p38-1","v":"y2v4","y":2,"o":19,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing  for example  some third year groups moved fairly unusually throughout the day yesterday  furthermore  these groups are always closely related to nagumo s group or kiriyama s group  when i looked into it  i noticed something pretty interesting   3rd place  third year group kiriyama   150 points    the printed top ten","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p38-1\"><h3><span class=\"ttl\">Kiriyama mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.38, 48<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “For example, some third-year groups moved fairly unusually throughout the day yesterday. Furthermore, these groups are always closely related to Nagumo’s group or Kiriyama’s group. When I looked into it, I noticed something pretty interesting.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “3rd Place: Third-Year Group Kiriyama – 150 Points” — the printed top-ten.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p95-1\">→ After: Ch.4: The plan against Kouenji<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p95-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani nagumo-miyabi kouenji-rokusuke kiriyama-ikuto","q":"kiriyama ikuto ch 4  the plan against kouenji on the tenth day after the test ended  ikuto kiriyama  third year of class b  closes his eyes once after a walkie talkie call   kouenji sits atop the podium with 230 points to nagumo s 236  six points apart  and kiriyama  nagumo s right hand  quietly closes his eyes at the news   kiriyama  don t you think nagumo s answer is a step backwards  if so  you would have been in a position to take the lead by starting of the second part of the test    mikitani   all i could think was   don t get carried away just because you re wealthy   the main reason why kouenji has not been appreciated is that he doesn t have a sincere attitude towards things   i don t know what happened  but kouenji has literally gone all out in this special survey of the uninhabited island   if left unchecked  kouenji will definitely finish the exam in the top three places  in some cases  it wouldn t even be possible for me to reach nagumo  losing to a group from the younger years was a problem  but losing to a loner would be a disgrace for the third year   the six groups that i have in custody  i am mobilizing them all   the only threat is kouenji  and other than that  there is plenty of time to go after destroying him  we will be able to see the results until the end of the 12th  in two days starting tomorrow  we will fully contain kouenji  once kouenji loses his momentum  he won t be able to surface again   i don t think you have to worry about that anymore  nagumo s fears are unfounded   an invisible ghost grabbed me by the shoulders  i am not surprised    no  this is mikitani s line  let me check  mikitani said  an invisible ghost  no   kiriyama says this  the speaker of  an invisible ghost grabbed me by the shoulders  i am not surprised  is kiriyama   do you want me to put you in charge    mikitani   unlike you  who have decided to win  i have to earn nagumo s reputation   but you also have to get second place  right  don t waste your time on unnecessary things    mikitani   there is no one who can stop kouenji except nagumo and me  that is the end of the story  calm strategist for nagumo   sees kouenji as the only real obstacle  plans an encirclement with six  free groups   nagumo s 15 reserved three person groups  two teams each free to act  and takes direct command personally to earn nagumo s reputation rather than  win  by his own count  his class b subordinate  groans at the six group plan  nagumo handed him the free groups  kiriyama acts as his eyes  the obstacle  230 vs 236  two days to contain him","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p95-1\"><h3><span class=\"ttl\">Ch.4: The plan against Kouenji<\/span><span class=\"meta\">Y2V4 · p.95–99<\/span><\/h3><p class=\"setup\">On the tenth day after the test ended, Ikuto Kiriyama, third year of Class B, closes his eyes once after a walkie-talkie call — Kouenji sits atop the podium with 230 points to Nagumo’s 236, six points apart, and Kiriyama, Nagumo’s right hand, quietly closes his eyes at the news.<\/p><p class=\"with\">with <a href=\"mikitani.html\">Mikitani<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Kiriyama. Don’t you think Nagumo&#x27;s answer is a step backwards? If so, you would have been in a position to take the lead by starting of the second part of the test.” — Mikitani.<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\">“All I could think was: ‘Don&#x27;t get carried away just because you&#x27;re wealthy.’”<span class=\"pg\">p.95<\/span><\/li><li class=\"q spoken\">“The main reason why Kouenji has not been appreciated is that he doesn’t have a sincere attitude towards things.”<span class=\"pg\">p.96<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what happened, but Kouenji has literally gone all out in this special survey of the uninhabited island.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If left unchecked, Kouenji will definitely finish the exam in the top three places. In some cases, it wouldn’t even be possible for me to reach Nagumo. Losing to a group from the younger years was a problem, but losing to a loner would be a disgrace for the third year.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The six groups that I have in custody. I am mobilizing them all”.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The only threat is Kouenji, and other than that, there is plenty of time to go after destroying him. We will be able to see the results until the end of the 12th. In two days starting tomorrow, we will fully contain Kouenji. Once Kouenji loses his momentum, he won&#x27;t be able to surface again.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think you have to worry about that anymore. Nagumo&#x27;s fears are unfounded.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “An invisible ghost grabbed me by the shoulders, I am not surprised.” — no, this is Mikitani&#x27;s line? Let me check: Mikitani said “An invisible ghost...”? No — Kiriyama says this. The speaker of “An invisible ghost grabbed me by the shoulders, I am not surprised.” is Kiriyama.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want me to put you in charge?” — Mikitani.<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unlike you, who have decided to win, I have to earn Nagumo&#x27;s reputation.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But you also have to get second place, right? Don&#x27;t waste your time on unnecessary things.” — Mikitani.<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is no one who can stop Kouenji except Nagumo and me. That is the end of the story.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm strategist for Nagumo — sees Kouenji as the only real obstacle, plans an encirclement with six “Free Groups” (Nagumo’s 15 reserved three-person groups, two teams each free to act), and takes direct command personally to earn Nagumo’s reputation rather than “win” by his own count.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> His Class B subordinate; groans at the six-group plan.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Nagumo handed him the Free Groups; Kiriyama acts as his eyes.<span class=\"pg\">p.95–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The obstacle: 230 vs 236; two days to contain him.<span class=\"pg\">p.95–99<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p38-1\">← Before: Kiriyama mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p100-1\">→ After: Ch.4: The morning siege; the departure<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p100-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kouenji-rokusuke kiriyama-ikuto","q":"kiriyama ikuto ch 4  the morning siege  the departure six free groups plus kiriyama s group surround kouenji s tent at 6 30  he sleeps on through the approach  they decide to settle in at his departure   never within two meters   and gps is declared fallible  not teacher proof   hey  why don t we go around him and block him before he leaves the tent  if we make it impossible for him to leave the tent  kouenji won t be able to move   if we interfere with his departure  we can delay the time it takes to reach the designated area  but what would your excuse be if a third party saw the situation  if you are going to interfere  you must refrain from doing something that can be easily recognized   why don t you do a gps search  anyway  there are a lot of points to spend     our tablets don t know where the teachers are  do not forget that the search is not absolute  as originally planned  we ll be settling in when kouenji clears the tent and starts moving  if you come across a freshman or sophomore  or an adult on your way to set a task  immediately open a distance of at least two meters from kouenji   it s on the move  it s kouenji   go   can you give me some time  kouenji    the third years call out  not kiriyama alone   i didn t expect you to do so well in this special exam   you know what i mean  kouenji  you ve got too many points   i want you to stay where you are the rest of the day   then you don t have to worry about me  right    kouenji   it is a matter of precaution  also  it is difficult for a third year student to accept the fact that he is competing for the highest position with you  a lonely student  the plan is passive   surround  isolate  never touch  he trusts discipline over confrontation  the 7 00 designated zone timing is his weapon  kouenji bolts the moment the zone is revealed  his siege is intimidation  never contact  kouenji flees the moment the zone appears  his hothead  restrains him twice","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p100-1\"><h3><span class=\"ttl\">Ch.4: The morning siege; the departure<\/span><span class=\"meta\">Y2V4 · p.100–102<\/span><\/h3><p class=\"setup\">Six free groups plus Kiriyama’s group surround Kouenji’s tent at 6:30; he sleeps on through the approach; they decide to settle in at his departure — never within two meters — and GPS is declared fallible (not teacher-proof).<\/p><p class=\"with\">with <a href=\"mikitani.html\">Mikitani<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Hey, why don&#x27;t we go around him and block him before he leaves the tent? If we make it impossible for him to leave the tent, Kouenji won&#x27;t be able to move.”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">“If we interfere with his departure, we can delay the time it takes to reach the designated area. But what would your excuse be if a third party saw the situation? If you are going to interfere, you must refrain from doing…”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">“Why don&#x27;t you do a GPS search? Anyway, there are a lot of points to spend. ”<span class=\"pg\">p.100<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “If we interfere with his departure, we can delay the time it takes to reach the designated area. But what would your excuse be if a third party saw the situation? If you are going to interfere, you must refrain from doing something that can be easily recognized.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our tablets don&#x27;t know where the teachers are. Do not forget that the search is not absolute. As originally planned, we&#x27;ll be settling in when Kouenji clears the tent and starts moving. If you come across a freshman or sophomore, or an adult on your way to set a task, immediately open a distance of at least two meters from Kouenji.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s on the move, it&#x27;s Kouenji!”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Go.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you give me some time, Kouenji?” — the third-years call out; not Kiriyama alone.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I didn&#x27;t expect you to do so well in this special exam.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You know what I mean, Kouenji. You&#x27;ve got too many points.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want you to stay where you are the rest of the day.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then you don&#x27;t have to worry about me, right?” — Kouenji.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is a matter of precaution. Also, it is difficult for a third year student to accept the fact that he is competing for the highest position with you, a lonely student.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The plan is passive — surround, isolate, never touch; he trusts discipline over confrontation; the 7:00 designated-zone timing is his weapon; Kouenji bolts the moment the zone is revealed.<span class=\"pg\">p.100–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> His siege is intimidation, never contact; Kouenji flees the moment the zone appears.<span class=\"pg\">p.100–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> His hothead; restrains him twice.<span class=\"pg\">p.100–102<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p95-1\">← Before: Ch.4: The plan against Kouenji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p103-1\">→ After: Ch.4: The sleep revelation; the circle spreads<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p103-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kouenji-rokusuke kiriyama-ikuto","q":"kiriyama ikuto ch 4  the sleep revelation  the circle spreads six hours into the chase  kouenji is found asleep in broad daylight by the e3 task site  kiriyama s first doubt arrives when the rem hypersomnia claim reaches him   get up  kouenji  you ve been running for more than 10 days  so you took a nap from exhaustion  right   i m sure you will agree  i am a human being like you     if that s the case  then go ahead and take the rest of the day off  you must be exhausted from all this  you must listen to the kind advice of your elders   take the day off  that s kind of funny   don t  make an effort  if you could get rid of fatigue just with a little rest  no one would have a problem   you certainly look good  but like mikitani said  you ve run for the last 10 days or so with more energy than anyone  there s no question about it  since you ve probably repeatedly ranked first in the order of arrival  but even if you have extraordinary stamina  you should have reached your limit by now   i have a very short dream  i have an extremely low rem phase   the ideal average daily sleep time for a human being is about seven to eight hours  it is said that the ideal amount of sleep is between seven and eight hours a day  because more or less is not enough to maintain good health  however  those who sleep little are those who are predisposed to maintaining good health  even if they sleep less than six hours     it seemed strange to me to sleep in peace  but i suppose that is what there is    by the way  do you still need me   i don t care if you are physically strong or not  shut up    i m not here at all  don t worry about us   you seem quite belligerent when you say that   i m not one to accept advice  kiriyama   it s useless  i ll change my strategy  we will seal the matter  the rem claim breaks the math he ran on kouenji   he still cannot believe a loner can sustain this  orders the circle expanded for the third designated zone window  first impatience arises  his rem secret now terrifies kiriyama  he drops persuasion for containment","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p103-1\"><h3><span class=\"ttl\">Ch.4: The sleep revelation; the circle spreads<\/span><span class=\"meta\">Y2V4 · p.103–106<\/span><\/h3><p class=\"setup\">Six hours into the chase, Kouenji is found asleep in broad daylight by the E3 task site; Kiriyama’s first doubt arrives when the REM hypersomnia claim reaches him.<\/p><p class=\"with\">with <a href=\"mikitani.html\">Mikitani<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Get up, Kouenji! You&#x27;ve been running for more than 10 days, so you took a nap from exhaustion, right?”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “I&#x27;m sure you will agree. I am a human being like you. ”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “If that&#x27;s the case, then go ahead and take the rest of the day off. You must be exhausted from all this. You must listen to the kind advice of your elders.”<span class=\"pg\">p.104<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Take the day off? That&#x27;s kind of funny.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t… make an effort. If you could get rid of fatigue just with a little rest, no one would have a problem.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You certainly look good. But like Mikitani said, you&#x27;ve run for the last 10 days or so with more energy than anyone. There&#x27;s no question about it, since you&#x27;ve probably repeatedly ranked first in the order of arrival. But even if you have extraordinary stamina, you should have reached your limit by now.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a very short dream. I have an extremely low REM phase.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The ideal average daily sleep time for a human being is about seven to eight hours. It is said that the ideal amount of sleep is between seven and eight hours a day, because more or less is not enough to maintain good health. However, those who sleep little are those who are predisposed to maintaining good health, even if they sleep less than six hours. ”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seemed strange to me to sleep in peace, but I suppose that is what there is ...”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “By the way, do you still need me?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t care if you are physically strong or not, shut up ...”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not here at all, don&#x27;t worry about us.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You seem quite belligerent when you say that.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not one to accept advice, Kiriyama.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s useless, I&#x27;ll change my strategy. We will seal the matter.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The REM claim breaks the math he ran on Kouenji — he still cannot believe a loner can sustain this; orders the circle expanded for the third-designated-zone window; first impatience arises.<span class=\"pg\">p.103–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> His REM secret now terrifies Kiriyama; he drops persuasion for containment.<span class=\"pg\">p.103–106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p100-1\">← Before: Ch.4: The morning siege; the departure<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p106-1\">→ After: Ch.4: The circle strategy<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p106-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"mikitani kouenji-rokusuke nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  the circle strategy the third designated zone is announced  kouenji walks off mid threat  kiriyama orders the 18 person circle spread wide  the e3 english task is one person and 8 points  dodo michimichi takes first  kouenji second with four points  the circle quietly fails to stop him even once   i m the one in charge now  don t interrupt the circle  mikitani   kouenji  don t be so harsh   well  well  they re getting noisy  so  let me pick up the pace a bit   shut  i won t let him get away twice  catch him and drag him   do not lose sight that the target is kouenji   there is a task at e3 that kouenji can participate in  but the reward is 8 points for first place or    this is your last warning  kouenji   only tomorrow  take our advice and stay put  that s it   if we can keep him at bay for a day  nagumo will be able to escape with the safe first place  the important thing is not to let kouenji take the top spot again   if we can keep him at bay for a day  nagumo will be able to escape with the safe first place  tactical flailing   the circle  the task blocking  all failures  his pride as a third year breaks  the teachers signal but the siege continues  he settles on two days of containment with nagumo s safe first as the prize  the e3 english task   dodo first  kouenji second with 4 points  the siege wins nothing  keep kouenji contained two days  nagumo s safe first is the goal now","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p106-1\"><h3><span class=\"ttl\">Ch.4: The circle strategy<\/span><span class=\"meta\">Y2V4 · p.106–110<\/span><\/h3><p class=\"setup\">The third-designated zone is announced; Kouenji walks off mid-threat; Kiriyama orders the 18-person circle spread wide; the E3 English task is one-person and 8 points; Dodo Michimichi takes first, Kouenji second with four points; the circle quietly fails to stop him even once.<\/p><p class=\"with\">with <a href=\"mikitani.html\">Mikitani<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I&#x27;m the one in charge now. Don&#x27;t interrupt the circle, Mikitani.”<span class=\"pg\">p.106<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mikitani<\/b> “Kouenji! Don&#x27;t be so harsh!”<span class=\"pg\">p.107<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Well, well, they&#x27;re getting noisy. So, let me pick up the pace a bit.”<span class=\"pg\">p.107<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Shut! I won&#x27;t let him get away twice! Catch him and drag him!”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do not lose sight that the target is Kouenji.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is a task at E3 that Kouenji can participate in. But the reward is 8 points for first place or ...”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is your last warning, Kouenji.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Only tomorrow. Take our advice and stay put. That&#x27;s it.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we can keep him at bay for a day, Nagumo will be able to escape with the safe first place. The important thing is not to let Kouenji take the top spot again.”<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we can keep him at bay for a day, Nagumo will be able to escape with the safe first place.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Tactical flailing — the circle, the task-blocking, all failures; his pride as a third-year breaks; the teachers signal but the siege continues; he settles on two days of containment with Nagumo’s safe first as the prize.<span class=\"pg\">p.106–110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The E3 English task — Dodo first, Kouenji second with 4 points; the siege wins nothing.<span class=\"pg\">p.106–110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Keep Kouenji contained two days; Nagumo’s safe first is the goal now.<span class=\"pg\">p.109–110<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p103-1\">← Before: Ch.4: The sleep revelation; the circle spreads<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p110-1\">→ After: Ch.4: The walk-through; the plan that failed<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p110-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"kouenji-rokusuke mikitani morooka nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto ch 4  the walk through  the plan that failed at the last designated zone  kouenji is ordered to stay  mikitani grabs him  he simply walks through the circle   morooka breaks his arm on contact  kouenji doesn t even break stride   i m sure you heard us  i m going to ask you to stay here tomorrow and the next day   are you asking me for a favor   no  it s an order   it is a request that i cannot ignore  but what happens if i refuse   in the worst case  you will be expelled   i don t obey anyone   then i will make you obey me  you understand  kouenji  right kiriyama    mikitani   as long as kouenji obeys  i will leave it up to you   it is not a pretty situation  i don t like male sexuality   what would you do  if you try to push me away  i will take it as a declaration of war   oh i see  it was as if a large rock was slowly crashing into mikitani  and before he knew it  he was forced to move to the side to give way   what  i think i have broken my arm    morooka  not rostered   no matter what you say  it doesn t change the fact that you pushed morooka away    printed untagged  mikitani or kiriyama  not assigned   i have no intention of showing mercy to those who prevent me from moving forward  much less turning against me    ah  if that s the case  i ll go down with kouenji in my arms  let s do it   it s not nice that you always follow me  it s not nice to have a dead leaf slapping my cheek over and over again   i see  it is true that the current mikitani was prepared to go after you until the end  if he was shown such an overwhelming skill difference  his spirit would be broken  but you are the only one who can devise and perform the trick of breaking your opponent s heart without counterattacking    kiriyama s read of kouenji   even if i have to drop the reward for reaching the designated area  here i will nip the counterattack of third year students in the bud   i ll go then  if it s okay with you   now if you ll excuse me  bye   do what you want  kouenji   there is always someone who does not agree with your calculations  like nagumo  the siege fails completely   his own named plan collapses in 15 minutes of walking  morooka s arm is broken  kiriyama s final analysis is not panic  the design was deliberate   make kouenji think the third years are nothing  so he walks out feeling no threat  the  big is better than small  hint is his next lever  the containment plan collapses in 15 minutes  kouenji walks out untouched  the spearhead breaks first  his disappointment  kiriyama s counter plot is revealed to himself   weaken kouenji s threat perception  not his score","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p110-1\"><h3><span class=\"ttl\">Ch.4: The walk-through; the plan that failed<\/span><span class=\"meta\">Y2V4 · p.110–115<\/span><\/h3><p class=\"setup\">At the last designated zone, Kouenji is ordered to stay; Mikitani grabs him; he simply walks through the circle — Morooka breaks his arm on contact; Kouenji doesn’t even break stride.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"mikitani.html\">Mikitani<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I&#x27;m sure you heard us. I&#x27;m going to ask you to stay here tomorrow and the next day.”<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> “Are you asking me for a favor?”<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\">“No, it&#x27;s an order.”<span class=\"pg\">p.110<\/span><\/li><\/ul><details class=\"more\"><summary>24 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It is a request that I cannot ignore, but what happens if I refuse?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the worst case, you will be expelled.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t obey anyone.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I will make you obey me. You understand, Kouenji? Right…Kiriyama.” — Mikitani.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As long as Kouenji obeys, I will leave it up to you.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not a pretty situation. I don&#x27;t like male sexuality.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What would you do? If you try to push me away, I will take it as a declaration of war.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh I see.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> It was as if a large rock was slowly crashing into Mikitani, and before he knew it, he was forced to move to the side to give way.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? I think I have broken my arm!” — Morooka (not rostered).<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “No matter what you say, it doesn&#x27;t change the fact that you pushed Morooka away.” — printed untagged; Mikitani or Kiriyama; not assigned.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have no intention of showing mercy to those who prevent me from moving forward, much less turning against me.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… Ah. If that&#x27;s the case, I&#x27;ll go down with Kouenji in my arms. Let&#x27;s do it!”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s not nice that you always follow me. It&#x27;s not nice to have a dead leaf slapping my cheek over and over again.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. It is true that the current Mikitani was prepared to go after you until the end. If he was shown such an overwhelming skill difference, his spirit would be broken. But you are the only one who can devise and perform the trick of breaking your opponent&#x27;s heart without counterattacking.” — Kiriyama’s read of Kouenji.<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I have to drop the reward for reaching the designated area, here I will nip the counterattack of third year students in the bud.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll go then, if it&#x27;s okay with you.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now if you&#x27;ll excuse me. Bye.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do what you want, Kouenji.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is always someone who does not agree with your calculations. Like Nagumo.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The siege fails completely — his own named plan collapses in 15 minutes of walking; Morooka’s arm is broken; Kiriyama’s final analysis is not panic: the design was deliberate — make Kouenji think the third-years are nothing, so he walks out feeling no threat; the “big is better than small” hint is his next lever.<span class=\"pg\">p.110–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The containment plan collapses in 15 minutes; Kouenji walks out untouched.<span class=\"pg\">p.110–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikitani<\/b> The spearhead breaks first.<span class=\"pg\">p.110–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> His disappointment; Kiriyama’s counter-plot is revealed to himself — weaken Kouenji’s threat perception, not his score.<span class=\"pg\">p.109–115<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p106-1\">← Before: Ch.4: The circle strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p207-1\">→ After: Kiriyama mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4-p207-1","v":"y2v4","y":2,"o":19,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing  the vacant space vice president kiriyama left intentionally open was reserved for you    nagumo explains the beach flags setup   however  it was surprising to see how kiriyama s group was left standing at the end of    narration","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4-p207-1\"><h3><span class=\"ttl\">Kiriyama mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.207, 280<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “the vacant space Vice President Kiriyama left intentionally open was reserved for you.” — Nagumo explains the Beach Flags setup.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “However, it was surprising to see how Kiriyama&#x27;s group was left standing at the end of” — narration.<span class=\"pg\">p.280<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4-p110-1\">← Before: Ch.4: The walk-through; the plan that failed<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4_5-p36-1","v":"y2v4.5","y":2,"o":20,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi horikita-manabu kiriyama-ikuto","q":"kiriyama ikuto kiriyama summons ayanokoji  the class a ticket and the expulsion of fifteen third years vice president kiriyama  message inviting him to the pool  is the most unlikely host imaginable  ayanokoji memorizes the results by the gym first  nagumo second  sakayanagi third  kiriyama s group fourth with 255 points   six short of the podium  all expulsions were third years  kiriyama waits by the pool  third years conspicuously absent from the quiet deck he chose  nagumo s allies are staring candidates  kiryuin teases them both before kiriyama abandons the poolside for a deck above   why did you want to bring me all the way out here   i won t beat around the bush  what did you do to nagumo on the last day of the uninhabited island exam  ayanokoji   give up  i don t know what you mean  my personal fight is still going on   now that nagumo s plan has changed  the others and i have started to see the adverse effects  i believe i told you before the uninhabited island exam  don t get in my way   it s true that i wanted to take down nagumo  if we couldn t beat him  it would be impossible for our class to rise back up to class a  however  that spirit gradually faded away by the time we reached the middle of our second year   we third years shifted to an individual competition early on  class points and school rules were of secondary importance  and we started playing according to the original rules proposed by nagumo   nagumo handed me a ticket to graduate from class a  so i decided to follow the rules that he made up that s what you wanted to hear  right   it was our mission to make sure that nagumo took first place  but your involvement disrupted the chain of command  leaving koenji to take first place while nagumo fell to second  the result was a significant loss in both class and private points   it costs 20 million points for a ticket to class a  so we re always looking for the best way to procure points  after this  you could say we re one ticket down   unable to do anything  those fifteen people were expelled  they didn t even have time to cry out   that guy has been playing around with the entire third year  the students without tickets are made to compete against each other  and then he ll make a show of giving the winning guy a ticket and make him pledge his allegiance   then what would you have me do  you won t tell me the details  but you won t see nagumo either  as it is  this is only going to get worse   that s fine  but you have to make a decision before nagumo makes his next move   i m going  if he knew we were meeting  things would become even more troublesome  his turn from nagumo s opponent to nagumo s ally is the structural fact of the third year  he predicts the stares will escalate and that nagumo will escalate beyond them  the 20 million point class a privilege is the core of nagumo s hold on his year  nagumo holds the class a tickets personally   held as verbal promises  not electronic transfers  individuals may hold up to 500 000 points  the rest being syphoned to nagumo  he pays off third years to clear the deck   quiet competence at arranging environments  once sworn to take him down  now one of his allies by coercion of 20 million points  he opposes the stares campaign even while following orders  summons him to extract the exam s last day secret  admits his own position  asks for a decision before nagumo s next move  ayanokoji invokes manabu s entrustment  kiriyama s face hardens at the name  fourth place with 255 points  six behind sakayanagi s third  the loss cost his group the top three bonus but also broke nagumo s chain of command  he accepts that his  backup  dispatch on short notice caused it","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4_5-p36-1\"><h3><span class=\"ttl\">Kiriyama summons Ayanokōji: the Class A ticket and the expulsion of fifteen third-years<\/span><span class=\"meta\">Y2V4.5 · p.36–53<\/span><\/h3><p class=\"setup\">Vice President Kiriyama, message inviting him to the pool, is the most unlikely host imaginable; Ayanokōji memorizes the results by the gym first: Nagumo second, Sakayanagi third, Kiriyama&#x27;s group fourth with 255 points — six short of the podium; all expulsions were third-years. Kiriyama waits by the pool; third-years conspicuously absent from the quiet deck he chose; Nagumo&#x27;s allies are staring candidates; Kiryūin teases them both before Kiriyama abandons the poolside for a deck above.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Why did you want to bring me all the way out here?”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\">“I won’t beat around the bush. What did you do to Nagumo on the last day of the uninhabited island exam, Ayanokōji?”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\">“Give up? I don&#x27;t know what you mean. My personal fight is still going on.”<span class=\"pg\">p.46<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Now that Nagumo&#x27;s plan has changed, the others and I have started to see the adverse effects. I believe I told you before the uninhabited island exam, don&#x27;t get in my way.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s true that I wanted to take down Nagumo. If we couldn&#x27;t beat him, it would be impossible for our class to rise back up to Class A. However, that spirit gradually faded away by the time we reached the middle of our second year.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We third-years shifted to an individual competition early on. Class points and school rules were of secondary importance, and we started playing according to the original rules proposed by Nagumo.”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo handed me a ticket to graduate from Class A, so I decided to follow the rules that he made up…That&#x27;s what you wanted to hear, right?”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was our mission to make sure that Nagumo took first place. But your involvement disrupted the chain of command, leaving Kōenji to take first place while Nagumo fell to second. The result was a significant loss in both class and private points.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It costs 20 million points for a ticket to Class A, so we&#x27;re always looking for the best way to procure points. After this, you could say we&#x27;re one ticket down.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unable to do anything, those fifteen people were expelled. They didn&#x27;t even have time to cry out.”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That guy has been playing around with the entire third year. The students without tickets are made to compete against each other, and then he&#x27;ll make a show of giving the winning guy a ticket and make him pledge his allegiance.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then what would you have me do? You won&#x27;t tell me the details, but you won&#x27;t see Nagumo either. As it is, this is only going to get worse.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…That&#x27;s fine. But you have to make a decision before Nagumo makes his next move.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m going. If he knew we were meeting, things would become even more troublesome.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> His turn from Nagumo&#x27;s opponent to Nagumo&#x27;s ally is the structural fact of the third-year; he predicts the stares will escalate and that Nagumo will escalate beyond them; the 20-million-point Class A privilege is the core of Nagumo&#x27;s hold on his year.<span class=\"pg\">p.46–53<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Nagumo holds the Class A tickets personally — held as verbal promises, not electronic transfers; individuals may hold up to 500,000 points, the rest being syphoned to Nagumo.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> He pays off third-years to clear the deck — quiet competence at arranging environments.<span class=\"pg\">p.44–45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Once sworn to take him down; now one of his allies by coercion of 20 million points; he opposes the stares campaign even while following orders.<span class=\"pg\">p.46–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Summons him to extract the exam&#x27;s last-day secret; admits his own position; asks for a decision before Nagumo&#x27;s next move.<span class=\"pg\">p.45–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Ayanokōji invokes Manabu&#x27;s entrustment; Kiriyama&#x27;s face hardens at the name.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Fourth place with 255 points, six behind Sakayanagi&#x27;s third; the loss cost his group the top-three bonus but also broke Nagumo&#x27;s chain of command; he accepts that his &quot;backup&quot; dispatch on short notice caused it.<span class=\"pg\">p.37<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4_5-p153-1\">→ After: Mentions: Nagumo&#x27;s safety net<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v4_5-p153-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto mentions  nagumo s safety net  fully understood that kiriyama had joined nagumo s side  as nagumo approached us  he stood next to ichinose   kiriyama had seen me and kei together  however  i didn t give any definite indication that we were dating","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v4_5-p153-1\"><h3><span class=\"ttl\">Mentions: Nagumo&#x27;s safety net<\/span><span class=\"meta\">Y2V4.5 · p.153–154<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> &quot;fully understood that Kiriyama had joined Nagumo&#x27;s side. As Nagumo approached us, he stood next to Ichinose.&quot;<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Kiriyama had seen me and Kei together. However, I didn&#x27;t give any definite indication that we were dating.&quot;<span class=\"pg\">p.154<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v4_5-p36-1\">← Before: Kiriyama summons Ayanokōji: the Class A ticket and the expulsion of fifteen third-years<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v7-p78-1","v":"y2v7","y":2,"o":23,"k":"spoken","w":"nagumo-miyabi yagami-takuya kiriyama-ikuto","q":"kiriyama ikuto the vice president  the thorny remark  the kishi rumor  2   the student council room  the members are already there except for student council president nagumo  kiriyama senpai  the third year vice president  is present  yagami and aga chat with ichinose san   it was decided in almost half a day  it seems that the student council president s decision was correct  however  if the decision was made by the student    council  i wish you would have informed us a little earlier    kiriyama senpai  the vice president  made a thorny remark   from my class    kiriyama   sorry  that s news to me  i don t understand why you would bet a lot of money to get someone expelled in the first place    kiriyama   who told you that nonsense    printed untagged  not assigned  the thorny remarks  the kishi rumor s origin sits in his class  both present in the room   the vice president and the secretary","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v7-p78-1\"><h3><span class=\"ttl\">The vice president: the thorny remark, the Kishi rumor<\/span><span class=\"meta\">Y2V7 · p.78–79<\/span><\/h3><p class=\"setup\">§2 — the student council room; the members are already there except for Student Council President Nagumo; Kiriyama-senpai, the third-year vice president, is present; Yagami and Aga chat with Ichinose-san.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It was decided in almost half a day? It seems that the student council president&#x27;s decision was correct. However, if the decision was made by the student …  council, I wish you would have informed us a little earlier.” …”<span class=\"pg\">p.78–79<\/span><\/li><li class=\"q spoken\">“From my class?” — Kiriyama.<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">“Sorry, that&#x27;s news to me. I don&#x27;t understand why you would bet a lot of money to get someone expelled in the first place.” — Kiriyama.<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It was decided in almost half a day? It seems that the student council president&#x27;s decision was correct. However, if the decision was made by the student …  council, I wish you would have informed us a little earlier.” — Kiriyama-senpai, the vice president, made a thorny remark.<span class=\"pg\">p.78–79<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Who told you that nonsense?” — printed untagged; not assigned.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> The thorny remarks; the Kishi rumor&#x27;s origin sits in his class.<span class=\"pg\">p.78–79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Both present in the room — the vice president and the secretary.<span class=\"pg\">p.78<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v9-p26-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"nagumo-miyabi ayanokouji-kiyotaka kiriyama-ikuto","q":"kiriyama ikuto kiriyama  the 20 million point bet and his last stand as nagumo and ayanokoji finalize the bet on the student council election  kiriyama makes a final attempt to stop a game staking 20 million points and ayanokoji s expulsion   i ll get you the contract  it s one of two things  expulsion or 20 million   you don t have to risk your expulsion to play along with nagumo s game  he tries to warn horikita that ayanokoji has been drawn into something  but nagumo talks over him  and he is left holding his forehead   wait a minute  president  ayanokouji kun is here because  the pragmatic vice president   deeply uneasy about the stakes and the hidden bet  unable to rein in nagumo  and worried about ayanokoji being drawn in  his president  he cannot stop his impulsive high stakes game  tries to warn him off the gamble  notes he no longer hides his true nature","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v9-p26-1\"><h3><span class=\"ttl\">Kiriyama: the 20-million-point bet and his last stand<\/span><span class=\"meta\">Y2V9 · p.26–28<\/span><\/h3><p class=\"setup\">As Nagumo and Ayanokōji finalize the bet on the student-council election, Kiriyama makes a final attempt to stop a game staking 20 million points and Ayanokōji&#x27;s expulsion. He tries to warn Horikita that Ayanokōji has been drawn into something, but Nagumo talks over him, and he is left holding his forehead.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I&#x27;ll get you the contract. It&#x27;s one of two things: expulsion or 20 million.&quot;<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\">&quot;You don&#x27;t have to risk your expulsion to play along with Nagumo&#x27;s game.&quot;<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\">&quot;Wait a minute, President. Ayanokouji-kun is here because...&quot;<span class=\"pg\">p.28<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The pragmatic vice president — deeply uneasy about the stakes and the hidden bet, unable to rein in Nagumo, and worried about Ayanokōji being drawn in.<span class=\"pg\">p.26–28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> His president; he cannot stop his impulsive high-stakes game.<span class=\"pg\">p.26–28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tries to warn him off the gamble; notes he no longer hides his true nature.<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v9-p75-1\">→ After: Kiriyama: inauguration, then exposed as the shoplifting mastermind<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v9-p75-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"horikita-suzune kiryuin-fuuka nagumo-miyabi kiriyama-ikuto","q":"kiriyama ikuto kiriyama  inauguration  then exposed as the shoplifting mastermind at the handover he reminds ayanokoji their battle is not over   see you  ayanokouji  our battle isn t over yet  he arranges the student council hearing at nagumo s request and acts as the  familiar third party  but horikita s reasoning   that yamanaka and tachibana feared someone more than nagumo   lands on him   i understand that kiryuuin s upset that she was almost made to look like a shoplifter   there s no guarantee that the information ayanokouji has given you is true  as witnesses are about to be called  he confesses  he used nagumo s message assigning him a point earning job as cover and had yamanaka frame kiryuin   got it  let s stop this now   it means that there s no need to call witnesses  i admit that it was me who   i m sorry kiryuuin  but it had to be you  in order to achieve my goal  calculating and proud   a guaranteed class a ticket meant he would never move against nagumo  so he chose kiryuin as the target  cornered by solid logic  he owns the plot rather than drag witnesses into it  her first case as president sees through him  he confesses  he admits he framed her deliberately  cites his class a ticket as proof he had no motive  used his message as cover","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v9-p75-1\"><h3><span class=\"ttl\">Kiriyama: inauguration, then exposed as the shoplifting mastermind<\/span><span class=\"meta\">Y2V9 · p.75, 183–190<\/span><\/h3><p class=\"setup\">At the handover he reminds Ayanokōji their battle is not over. He arranges the student-council hearing at Nagumo&#x27;s request and acts as the &quot;familiar third party,&quot; but Horikita&#x27;s reasoning — that Yamanaka and Tachibana feared someone more than Nagumo — lands on him. As witnesses are about to be called, he confesses: he used Nagumo&#x27;s message assigning him a point-earning job as cover and had Yamanaka frame Kiryūin.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kiryuin-fuuka.html\">Kiryuin Fuuka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;See you, Ayanokouji. Our battle isn&#x27;t over yet.&quot;<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\">&quot;I understand that Kiryuuin&#x27;s upset that she was almost made to look like a shoplifter.&quot;<span class=\"pg\">p.185<\/span><\/li><li class=\"q spoken\">&quot;There&#x27;s no guarantee that the information Ayanokouji has given you is true.&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Got it. Let&#x27;s stop this now.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It means that there&#x27;s no need to call witnesses. I admit that it was me who...&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m sorry Kiryuuin, but it had to be you, in order to achieve my goal.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calculating and proud — a guaranteed Class A ticket meant he would never move against Nagumo, so he chose Kiryūin as the target; cornered by solid logic, he owns the plot rather than drag witnesses into it.<span class=\"pg\">p.183–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her first case as president sees through him; he confesses.<span class=\"pg\">p.188–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> He admits he framed her deliberately.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Cites his Class A ticket as proof he had no motive; used his message as cover.<span class=\"pg\">p.188–190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kiriyama-ikuto-y2v9-p26-1\">← Before: Kiriyama: the 20-million-point bet and his last stand<\/button><\/div><\/article>"},{"i":"sc-kiriyama-ikuto-y2v9_5-p120-1","v":"y2v9.5","y":2,"o":26,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama mentioned in passing named in this volume  passing mention  locator pages  p 120  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v9_5-p120-1\"><h3><span class=\"ttl\">Kiriyama mentioned in passing<\/span><span class=\"meta\">Y2V9.5 · p.120<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.120; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kiriyama-ikuto-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"kiriyama-ikuto","q":"kiriyama ikuto kiriyama ikuto mentioned in passing named in this volume  passing mention  locator pages  p 169  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-kiriyama-ikuto-y2v12-p12-1\"><h3><span class=\"ttl\">kiriyama-ikuto mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.169; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"}];
